/* Service worker for the catalogue app (generated by build.py from site/sw.js).
   - Opens the app without internet once it has been opened online one time.
   - Keeps the AI files (several MB each) after the first download, across app updates.
   - Receives photos, product lists and backups shared from other apps (Android "Share").
   Products and photos are not stored here: they stay in the phone's browser storage. */
const VERSION = '__VERSION__';
const AI_VERSION = '__AI_VERSION__';
const PRECACHE = __PRECACHE__;
const APP_CACHE = 'app-' + VERSION;
const AI_CACHE = 'ai-files';
const SHARE_CACHE = 'share-inbox';
const SCOPE = new URL(self.registration.scope);
const SHELL = new URL('./', SCOPE).href;

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(APP_CACHE);
    await c.addAll(PRECACHE.map(u => new Request(new URL(u, SCOPE), { cache: 'reload' })));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('app-') && k !== APP_CACHE) await caches.delete(k);
    // drop AI files of older library versions
    const ai = await caches.open(AI_CACHE);
    for (const r of await ai.keys()) if (!r.url.includes('/vendor/imgly/' + AI_VERSION + '/')) await ai.delete(r);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request, url = new URL(req.url);
  if (url.origin !== SCOPE.origin) return; // the app loads nothing from other sites
  if (req.method === 'POST' && url.pathname === new URL('share-target', SCOPE).pathname) { e.respondWith(receiveShare(req)); return; }
  if (req.method !== 'GET') return;
  if (req.mode === 'navigate') { e.respondWith(page(e)); return; }
  if (url.pathname.includes('/vendor/')) { e.respondWith(cacheFirst(req, AI_CACHE)); return; }
  if (/\/(assets|icons)\//.test(url.pathname) || url.pathname.endsWith('/manifest.webmanifest')) { e.respondWith(cacheFirst(req, APP_CACHE)); return; }
});

// The page: network first so updates arrive, the saved copy when offline or very slow.
async function page(e) {
  const c = await caches.open(APP_CACHE);
  const net = fetch(e.request).then(res => {
    if (res.ok && res.type === 'basic') c.put(SHELL, res.clone());
    return res;
  });
  e.waitUntil(net.catch(() => { }));
  const timeout = new Promise(r => setTimeout(r, 5000, null));
  try {
    const res = await Promise.race([net, timeout]);
    if (res) return res;
  } catch (err) { /* offline */ }
  return (await c.match(SHELL)) || net;
}

async function cacheFirst(req, name) {
  const c = await caches.open(name);
  const hit = await c.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok) c.put(req, res.clone());
  return res;
}

// Android share sheet → store the files, then open the app, which picks them up.
async function receiveShare(req) {
  let count = 0;
  const stamp = Date.now().toString(36);
  try {
    const form = await req.formData();
    const c = await caches.open(SHARE_CACHE);
    for (const f of form.getAll('files')) {
      if (!f || typeof f === 'string' || !f.size) continue;
      await c.put(new Request(new URL(`share-inbox/${stamp}/${count}`, SCOPE)), new Response(f, {
        headers: { 'Content-Type': f.type || 'application/octet-stream', 'X-File-Name': encodeURIComponent(f.name || `shared-${count + 1}`) }
      }));
      count++;
    }
  } catch (err) { /* opened without files: just open the app */ }
  return Response.redirect(new URL(count ? `./?share=${stamp}` : './', SCOPE).href, 303);
}

self.addEventListener('message', (e) => { if (e.data === 'skip-waiting') self.skipWaiting(); });
